<template><div class="integration-workspace"><h2>Complete Core cross-omics evidence</h2><p>Genome-anchored gene means, exact transcript pairs, original record distributions and named species comparisons retain their distinct populations.</p><p v-if="context.error.value" role="alert">{{ context.error.value }} <button class="btn subtle" @click="context.refresh">Retry integration</button></p><p v-if="context.status.value!=='ready'">Preparation: {{ context.status.value }}</p><template v-if="ready"><section v-for="section in sections" :id="'integration-'+section.name" :key="section.name"><h2>{{ section.name }} · {{ section.title }}</h2><IntegrationCohortSelector v-if="section.name==='X7'" :context="context" /><div class="integration-grid"><IntegrationFigure v-for="id in section.ids" :key="speciesId+id" :chart-id="id" :figure="context.charts[id]" :context="context" :species-id="speciesId" :class="{'integration-wide':wide.includes(id)}" @selection="select" @entity="$emit('entity',$event)" /></div><details v-for="table in section.tables||[]" :key="table" @toggle="tableOpen[table]=$event.target.open"><summary>Complete result table · {{ table }}</summary><IntegrationResultTable v-if="tableOpen[table]" :context="context" :species-id="speciesId" :table-id="table" :title="table" @entity="$emit('entity',$event)" /></details><template v-if="section.name==='X6'"><details @toggle="atlasOpen=$event.target.open"><summary>All {{ context.manifest.value.coverage.numeric_core_fields }} original Core fields and exact distributions</summary><IntegrationFieldAtlas v-if="atlasOpen" :context="context" :species-id="speciesId" /></details><details @toggle="metadataOpen=$event.target.open"><summary>All {{ context.manifest.value.coverage.metadata_core_fields }} metadata fields and categories</summary><IntegrationMetadataTable v-if="metadataOpen" :context="context" /></details></template><IntegrationCandidateTable v-if="section.name==='X8'" :context="context" :species-id="speciesId" @entity="$emit('entity',$event)" /></section></template><IntegrationMembers ref="members" :context="context" :species-id="speciesId" :selection="selection" @close="selection=null" @entity="$emit('entity',$event)" /></div></template>
<script setup>
import {ref,reactive,watch,computed,nextTick} from 'vue';import IntegrationFigure from './IntegrationFigure.vue';import IntegrationMembers from './IntegrationMembers.vue';import IntegrationCohortSelector from './IntegrationCohortSelector.vue';import IntegrationResultTable from './IntegrationResultTable.vue';import IntegrationFieldAtlas from './IntegrationFieldAtlas.vue';import IntegrationMetadataTable from './IntegrationMetadataTable.vue';import IntegrationCandidateTable from './IntegrationCandidateTable.vue'
const props=defineProps({context:Object,speciesId:String});defineEmits(['entity']);const selection=ref(null),members=ref(),atlasOpen=ref(false),metadataOpen=ref(false),tableOpen=reactive({});const ready=computed(()=>props.context.manifest.value?.status==='ready');const wide=['CX05','CX07','CX11','CX12','CX13','CGT','CGP','CTP','CX15','CX16','CX17','XS02','XS03','XS04']
const sections=[{name:'X0',title:'Sources and strict mapping',ids:['CX01','CX02'],tables:['x0_mapping','x0_conflicts']},{name:'X1',title:'Nitrogen resource shifts',ids:['CX03','CX04','CX05','CX06'],tables:['x1_shifts']},{name:'X2',title:'GC coupling',ids:['CX07'],tables:['x2_gc']},{name:'X3',title:'Conditional protein properties',ids:['CX08','CX09','CX10'],tables:['x3_members']},{name:'X4',title:'Exact transcript-paired sequence agreement',ids:['CX11'],tables:['x4_pairs']},{name:'X5',title:'True outlier-set intersections',ids:['CX12']},{name:'X6',title:'All-feature coupling and original Core atlas',ids:['CX13','CGT','CGP','CTP','XS04'],tables:['x6_edges']},{name:'X7',title:'Real named species comparison',ids:['CX14','CX15','CX16','XS01'],tables:['x7_features']},{name:'X8',title:'Resource strata and complete candidate evidence',ids:['CX17','XS02','XS03']}]
async function select(s){selection.value=s;await nextTick();members.value?.$el?.scrollIntoView({block:'center',behavior:'instant'})}

watch(()=>props.context.manifest.value?.artifact_version,()=>selection.value=null)
</script>
<style src="./integration.css"></style>
